from pathlib import Path
import json,base64,html
C=Path(__file__).resolve().parents[1];R=C/'runs/V4';P=C/'review/previews/V4';O=Path('rural_delivery');O.mkdir(exist_ok=True)
d=json.loads((R/'params_used.json').read_text());plans=json.loads((P/'plans.json').read_text())
def img(n):return 'data:image/png;base64,'+base64.b64encode((P/n).read_bytes()).decode()
def figure(n,title):return f'<figure><img loading="lazy" src="{img(n)}" alt="{title}"><figcaption>{title}</figcaption></figure>'
hero=figure('village_close.png','模型预览 · 从最终 NBT 读回；近似材质，不是游戏截图')
views=''.join(figure(v+'_day.png',name+' · 日景')+figure(v+'_night.png',name+' · 夜景') for v,name in [('se','东南'),('sw','西南'),('ne','东北'),('nw','西北')])
homes=''
zh={'finished':'装修完成','old':'旧宅','frame':'裸露框架','brick':'砌墙未完工','hybrid':'下层入住／顶层待装修'}
for t in d['buildings']:
 items=[q for q in plans if q['house']==t['id']]
 homes+=f'<details><summary>{t["id"]}　{zh[t["kind"]]}　{t["w"]} × {t["d"]} 格 · {t["floors"]} 层</summary><div class="grid">'+''.join(figure(q['image'],f'{q["floor"]} 层 · 俯视切片') for q in items)+'</div></details>'
tech=''.join(figure(n,title) for n,title in [('section.png','R01 楼梯剖面'),('exploded.png','R01 楼层展开')]+[(f'elevation_{i}.png',['北','东','南','西'][i]+'立面') for i in range(4)])
text=f'''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>田埂里｜13栋乡村自建房</title><style>*{{box-sizing:border-box}}body{{margin:0;background:#f2efe5;color:#263c30;font-family:system-ui,"Microsoft YaHei",sans-serif}}header{{padding:70px max(6vw,24px) 35px;background:#243e30;color:#f4f0da}}header small{{letter-spacing:.22em;color:#c1cf96}}h1{{font-size:clamp(36px,6vw,74px);margin:20px 0}}header p{{max-width:740px;line-height:1.9}}nav{{padding:18px 6vw;position:sticky;top:0;background:#e6e6d8ef;display:flex;gap:24px;flex-wrap:wrap;z-index:3}}a{{color:inherit}}main{{max-width:1440px;padding:24px;margin:auto}}section{{padding:26px 0 46px;scroll-margin-top:75px}}h2{{font-size:28px;font-weight:500}}p,li{{line-height:1.9}}.grid{{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}}figure{{margin:12px 0;background:#fff;border-radius:8px;overflow:hidden}}figure img{{width:100%;display:block}}figcaption{{padding:14px 18px;font-size:14px;color:#596856}}details{{border-top:1px solid #bec4b5;padding:18px 0}}summary{{cursor:pointer;font-weight:600}}.tag{{display:inline-block;padding:9px 17px;margin:0 10px 8px 0;border:1px solid #81916b;border-radius:22px}}aside{{padding:20px 24px;background:#e4e7d6;border-left:3px solid #617949}}@media(max-width:700px){{.grid{{grid-template-columns:1fr}}}}</style><header><small>HAIBARA’S ARCHITECT / COUNTRYSIDE STUDY 01</small><h1>田埂里</h1><p>13 栋自建房，沿着村路错落展开。新房的檐线、旧宅的瓦顶、未封闭的框架与分批施工的砖墙共同组成村落；田埂、菜地和耕地围绕并伸入日常生活。</p><span class="tag">6 栋已装修</span><span class="tag">4 栋旧宅</span><span class="tag">3 栋未完工</span><span class="tag">Java 1.21.1</span></header><nav><a href="#overview">整体</a><a href="#site">田与路</a><a href="#homes">逐栋逐层</a><a href="#views">四向昼夜</a><a href="#record">制作记录</a></nav><main><section id="overview">{hero}<aside>世界存档已单独提供。页面中的图片均来自最终方块模型，材质与光照是离线近似；不冒充 Minecraft 客户端截图。</aside></section><section id="site"><h2>田埂随地块转折，村路绕着宅地生长</h2><p>场地 320 × 288 格，房屋 1–4 层。14 片外围耕地以田埂分隔，混合成熟小麦、胡萝卜、马铃薯、甜菜和休耕地；内部保留两片菜地。村道由一条主路、支路和入户短路组成，宅前以水泥地、土坪和低院墙组织使用。</p>{figure('top_day.png','垂直正交俯视 · 东 +X，北 −Z')}</section><section id="homes"><h2>每栋都可以打开看楼层</h2><p>已使用楼层安排起居、睡眠、厨房位置与楼梯；家具为方块表达，床具没有声明原生睡眠功能。未完工楼层保持施工状态。首层门洞保留净空，完整游戏碰撞仍待实测。</p>{homes}<div class="grid">{figure('home_cut.png','R01 内部剖切')}{figure('construction.png','裸露混凝土框架／施工场地')}</div></section><section id="views"><h2>四向昼夜</h2><p>同尺度、同俯角。所有已使用空间配置灯位；未完工楼层不补住宅灯。萤石与海晶灯仅表示材料差别，原版不传播彩色光。</p><div class="grid">{views}</div></section><section id="record"><h2>制作记录与参考边界</h2><p>参考 Bad_Door 的<a href="https://www.bilibili.com/video/BV1TpGw6JEHQ/">《如何像预制菜一样预制农村自建房》</a>。网页接口最初受限，随后通过浏览器查看了约 00:23 的预览、06:27 的开窗示范与 12:29 的屋顶设备片段，未声称完整观看。借鉴窗外防盗网、分层收口和屋面生活设施；村落总图、农田及室内布局为本次原创。</p><p>13 栋数量、最终 NBT 精确读回、13 个入口净空与 33,931 格作物承托检查通过。1.21.1 服务端加载与区块回读结果见工程包报告；客户端截图、玩家碰撞和容器交互未实测。农田中的小麦是原版作物，不称水稻。</p><div class="grid">{tech}</div><h2>关键词</h2><p>南方乡村自建房聚落，13栋，新修白墙小楼、砖墙旧宅、混凝土框架和半完工加层混合。不同面宽、进深与层数，局部L形占地、回廊阳台、外机和水管、防盗网、屋顶水箱与晒场。宅地错位，土坪与小院穿插，村路转折，外围不等大的耕地、灌溉沟与田埂包围，少量菜地伸入村内。保留门口、楼梯与田间通路，避免整排相同房子。</p></section></main></html>'''
(O/'Rural13.html').write_text(text,encoding='utf-8');print('html',len(text))
